@if(in_array($order->payment_status,['pending','observed']))<section class="card section"><h2>Transferencia del 100 %</h2><h3>Total a transferir: ${{ number_format($order->total_clp,0,',','.') }} CLP</h3>@if($settings->bankIsReady())<dl>@foreach(['holder'=>'Titular','rut'=>'RUT','bank'=>'Banco','account_type'=>'Tipo de cuenta','account_number'=>'Número de cuenta','email'=>'Correo'] as $key=>$label)<dt><strong>{{ $label }}</strong></dt><dd>{{ $settings->bank_details[$key] }}</dd>@endforeach</dl><p>{{ $settings->payment_instructions }}</p><form method="POST" enctype="multipart/form-data" action="{{ route('payments.store',$order) }}" class="form-stack">@csrf<label>Comprobante de transferencia (JPG, PNG, WebP o PDF; máximo 5 MB)<input name="receipt" type="file" accept="image/jpeg,image/png,image/webp,application/pdf" required></label><button class="button">Enviar comprobante para verificación</button></form><p class="muted">Adjuntar un comprobante no confirma el ingreso del dinero. El equipo lo verificará manualmente.</p>@else<p class="notice">El taller aún no configura todos los datos bancarios. Las instrucciones y la carga de comprobantes se habilitarán cuando estén completos.</p>@endif</section>@endif
